<?php
require_once __DIR__.'/../../config/database.php';require_once __DIR__.'/../../includes/session.php';require_once __DIR__.'/../../includes/functions.php';require_once __DIR__.'/../../includes/admin_layout.php';if(!is_admin_logged_in())redirect('../../index.php');if(($_SESSION['admin_role']??'admin')!=='admin'){http_response_code(403);exit('Administrator access required.');}if($_SERVER['REQUEST_METHOD']==='POST'&&verify_csrf_token($_POST['csrf_token']??'')){pg_query_params($conn,'INSERT INTO officer_assignments(attendee_id,department_id,position,school_year) VALUES($1,$2,$3,$4) ON CONFLICT DO NOTHING',[(int)$_POST['attendee_id'],(int)$_POST['department_id']?:null,trim($_POST['position']),trim($_POST['school_year'])]);redirect('index.php');}$students=pg_query($conn,"SELECT id,attendee_code,full_name FROM attendees WHERE status='active' ORDER BY full_name");$departments=pg_query($conn,'SELECT * FROM departments ORDER BY name');$rows=pg_query($conn,"SELECT o.*,a.attendee_code,a.full_name,d.name department_name,(SELECT COUNT(*) FROM session_attendance sa JOIN event_registrations r ON r.id=sa.registration_id WHERE r.attendee_id=a.id AND sa.time_in_at IS NOT NULL) sessions_attended FROM officer_assignments o JOIN attendees a ON a.id=o.attendee_id LEFT JOIN departments d ON d.id=o.department_id ORDER BY o.is_active DESC,d.name,a.full_name");admin_page_start('Officers','officers');?>
<div class="hero"><div><h2><i class="fas fa-user-tie"></i> Student Officers</h2><p>Assign officer responsibilities while monitoring the same student attendance record.</p></div></div><div class="card"><form method="post" class="form-grid"><?=csrf_field()?><div class="field"><label>Student</label><select name="attendee_id"><?php while($s=pg_fetch_assoc($students)):?><option value="<?=(int)$s['id']?>"><?=h($s['attendee_code'].' · '.$s['full_name'])?></option><?php endwhile;?></select></div><div class="field"><label>Department</label><select name="department_id"><option value="">School-wide</option><?php while($d=pg_fetch_assoc($departments)):?><option value="<?=(int)$d['id']?>"><?=h($d['name'])?></option><?php endwhile;?></select></div><div class="field"><label>Officer position</label><input name="position" required></div><div class="field"><label>School year</label><input name="school_year" placeholder="2026-2027" required></div><div class="field full"><button class="btn">Assign Officer</button></div></form></div><div class="card"><table><thead><tr><th>Officer</th><th>Department</th><th>Position</th><th>School Year</th><th>Sessions Attended</th></tr></thead><tbody><?php while($o=pg_fetch_assoc($rows)):?><tr><td><strong><?=h($o['full_name'])?></strong><div class="help"><?=h($o['attendee_code'])?></div></td><td><?=h($o['department_name']?:'School-wide')?></td><td><?=h($o['position'])?></td><td><?=h($o['school_year'])?></td><td><?=(int)$o['sessions_attended']?></td></tr><?php endwhile;?></tbody></table></div><?php admin_page_end();?>
